function buildFromItems(items,nativeWdd,nativeEd){
  /* 1. 주차 목록 */
  var weekSet={};
  for(var i=0;i<items.length;i++)weekSet[items[i].week]=true;
  var weeks=Object.keys(weekSet).sort(function(a,b){return parseInt(a)-parseInt(b);});
  wks=weeks;

  /* 2. 주차별 날짜 맵 - native wdd 우선 */
  if(nativeWdd){
    wdd=nativeWdd;
  }else{
    wdd={};
    for(var i=0;i<items.length;i++){
      var it=items[i];
      if(!wdd[it.week])wdd[it.week]={};
      wdd[it.week][it.day]=it.date;
    }
  }

  /* 3. 색상 맵 - 구별되는 초연한 파스텔 팔레트 */
  var palette=['#CFFAFE','#DCFCE7','#D1FAE5','#FCE7F3','#FEF3C7','#EDE9FE','#FFEDD5','#DBEAFE','#FEF9C3','#FFE4E6','#F3E8FF','#FEE2E2','#E0F2FE','#FDF4FF','#D1FAE5','#FFF7ED','#F0F9FF','#EDE9FE'];
  var pIdx=0;
  /* 1차: 일반 과목 색 배정 */
  for(var i=0;i<items.length;i++){
    var s=items[i].subject;
    if(!cmap[s]&&!isEx(s)){cmap[s]=palette[pIdx%palette.length];pIdx++;}
  }
  /* 2차: 시험 과목은 원 과목 색을 그대로 사용 (빨간 테두리로만 구분) */
  for(var i=0;i<items.length;i++){
    var s=items[i].subject;
    if(!cmap[s]){
      var base=examBase(s);
      if(base&&cmap[base])cmap[s]=cmap[base];
      else{cmap[s]=palette[pIdx%palette.length];pIdx++;}
    }
  }

  /* 4. 시험 날짜 목록 */
  if(nativeEd){
    ed=nativeEd;
  }else{
    var edSet={};
    for(var i=0;i<items.length;i++){if(items[i].is_exam)edSet[items[i].date]=true;}
    ed=Object.keys(edSet);
  }

  /* 5. merged 교체 */
  merged=items;

  /* 6. fsubj 재구성 - 과목명 기준으로 중복 제거 (교수명 다른 동일 과목 하나로) */
  var sSet={};
  for(var i=0;i<items.length;i++)sSet[items[i].subject]=true;
  fsubj=Object.keys(sSet).sort();
  fsubj2=fsubj.slice();

  /* 7. 주간 HTML 재구성 */
  wh={};
  wl={};
  for(var wi=0;wi<weeks.length;wi++){
    var w=weeks[wi];
    var weekItems=items.filter(function(it){return it.week===w;});
    wh[w]=buildWeekTable(w,weekItems);
    wl[w]=buildLegend(weekItems);
  }
}

var _subjColorMap=null;
function buildSubjColorMapFromWh(){
  var map={};
  Object.keys(wh).forEach(function(wk){
    var str=wh[wk]||'';
    var re=/style="background:([^"]+)"[^>]*>(?:<div class="cn-s"[^>]*>|<div class="cn-s cn-exam"[^>]*>)([^<]+)/g;
    var m;
    while((m=re.exec(str))!==null){
      var subj=m[2].replace(/\s*‼️\s*/g,'').trim();
      if(subj&&!map[subj])map[subj]=m[1].trim();
    }
  });
  return map;
}
function buildSubjColorMap(){
  _subjColorMap=buildSubjColorMapFromWh();
  if(Object.keys(_subjColorMap).length>0)return _subjColorMap;
  _subjColorMap={};
  var colors=['#14B8A6','#22C55E','#A78BFA','#F97316','#EC4899','#8B5CF6','#84CC16','#10B981','#D97706','#3B82F6'];
  (merged||[]).forEach(function(it){
    if(it.subject&&!_subjColorMap[it.subject]){
      var hash=0;for(var i=0;i<it.subject.length;i++)hash=(hash*31+it.subject.charCodeAt(i))&0xFFFF;
      _subjColorMap[it.subject]=colors[hash%colors.length];
    }
  });
  return _subjColorMap;
}
function getSubjectColor(subj){
  if(!_subjColorMap)buildSubjColorMap();
  if(_subjColorMap[subj])return _subjColorMap[subj];
  var colors=['#14B8A6','#22C55E','#A78BFA','#F97316','#EC4899','#8B5CF6','#84CC16','#10B981','#D97706','#3B82F6'];
  var hash=0;for(var i=0;i<(subj||'').length;i++)hash=(hash*31+subj.charCodeAt(i))&0xFFFF;
  return colors[hash%colors.length];
}
var GRADE_SUBJECTS={
  '의학과 1학년':['의학생화학','인체미세구조와 기능','인체반응 및 병태생리','생애주기',
    '인체미세구조 실습','인체질병형태학실습','실험및논문연구2',
    '환자의사사회1','문제바탕학습1','의료면담1'],
  '의학과 2학년':['호흡기학','알레르기-면역학','혈액학','근육골격계학',
    '모체-태아-주산기의학','생식의학','환자의사사회3',
    '임상의학입문 1-1','임상의학입문 2-1','문제바탕학습3','의료면담3'],
  '의예과 2학년':[]
};
function getUniqueSubjects(){
  /* 현재 시간표(merged) 기준 — 학기 바뀌어도 하드코딩 목록에 안 묶이게.
     '~시험' 항목 제외: 시험은 과목 선택 + 시험 체크로 추가 */
  var set={};
  for(var i=0;i<merged.length;i++){
    var s=merged[i].subject;
    if(s&&!isEv(s)&&!isHoliday(s)&&!isEx(s))set[s]=true;
  }
  var list=Object.keys(set);
  if(list.length)return list.sort(function(a,b){return a.localeCompare(b,'ko');});
  var fixed=GRADE_SUBJECTS[savedGrade||''];
  if(fixed&&fixed.length>0) return fixed;
  if(!_subjColorMap) buildSubjColorMap();
  return Object.keys(_subjColorMap).sort(function(a,b){return a.localeCompare(b,'ko');});
}
